import { createHash } from "node:crypto";
import { eq } from "drizzle-orm";

import type { createDatabase } from "../db/client.js";
import { apiKeys } from "../db/schema.js";

type Database = ReturnType<typeof createDatabase>["db"];

export function hashApiKey(key: string): string {
  return createHash("sha256").update(key, "utf8").digest("hex");
}

export async function validateApiKey(db: Database, key: unknown) {
  if (typeof key !== "string" || key.length === 0) {
    return null;
  }

  const [owner] = await db
    .select({ userId: apiKeys.userId })
    .from(apiKeys)
    .where(eq(apiKeys.keyHash, hashApiKey(key)))
    .limit(1);

  return owner ?? null;
}

import { sql } from "drizzle-orm";
import { check, customType, date, integer, pgTable, text, timestamp, unique, uuid } from "drizzle-orm/pg-core";

import { type Ad, adFormats, adStatuses, niches } from "../ads/index.js";

// Operational insertion provenance, not part of the public ad domain. Keep xid8
// as text: PostgreSQL transaction IDs must never pass through JS numbers.
const xid8 = customType<{ data: string; driverData: string }>({
  dataType: () => "xid8",
});

export const users = pgTable("users", {
  id: uuid("id").defaultRandom().primaryKey(),
  username: text("username").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
});

export const brands = pgTable("brands", {
  id: integer("id").primaryKey(),
  name: text("name").notNull(),
});

export const ads = pgTable(
  "ads",
  {
    id: text("id").primaryKey(),
    brandId: integer("brand_id")
      .notNull()
      .references(() => brands.id),
    headline: text("headline").notNull(),
    bodyText: text("body_text").notNull(),
    niche: text("niche").$type<Ad["niche"]>().notNull(),
    format: text("format", { enum: adFormats }).notNull(),
    status: text("status", { enum: adStatuses }).notNull(),
    startDate: date("start_date").notNull(),
    endDate: date("end_date"),
    impressionRank: integer("impression_rank"),
    countries: text("countries").array().notNull(),
    discoveredAt: timestamp("discovered_at", { withTimezone: true }).notNull(),
    insertedXid: xid8("inserted_xid").notNull().default(sql`pg_current_xact_id()`),
  },
  (table) => [
    // DDL requires literal catalog constants, not runtime bind parameters.
    check(
      "ads_niche_check",
      sql`${table.niche} IN (${sql.join(
        niches.map(({ slug }) => sql`${slug}`),
        sql`, `,
      )})`.inlineParams(),
    ),
    check(
      "ads_format_check",
      sql`${table.format} IN (${sql.join(
        adFormats.map((format) => sql`${format}`),
        sql`, `,
      )})`.inlineParams(),
    ),
    check(
      "ads_status_check",
      sql`${table.status} IN (${sql.join(
        adStatuses.map((status) => sql`${status}`),
        sql`, `,
      )})`.inlineParams(),
    ),
    check("ads_impression_rank_check", sql`${table.impressionRank} > 0`),
    check(
      "ads_status_end_date_check",
      sql`(${table.status} = 'active' AND ${table.endDate} IS NULL) OR (${table.status} = 'inactive' AND ${table.endDate} IS NOT NULL)`,
    ),
    check("ads_date_order_check", sql`${table.endDate} >= ${table.startDate}`),
    // PostgreSQL's default NULL-distinct uniqueness permits unknown ranks.
    unique("ads_brand_rank_unique").on(table.brandId, table.impressionRank),
  ],
);

export const apiKeys = pgTable("api_keys", {
  id: uuid("id").defaultRandom().primaryKey(),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id),
  keyHash: text("key_hash").notNull().unique(),
});

import { type FormEvent, useCallback, useEffect, useRef, useState } from "react";

import { AuthError, clearToken, getIdentity, login, readToken, storeToken, type User } from "./auth";
import "./styles.css";

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [checking, setChecking] = useState(true);
  const [unavailable, setUnavailable] = useState(false);
  const generation = useRef(0);

  const restore = useCallback(async () => {
    const request = ++generation.current;
    setUser(null);
    setChecking(true);
    setBusy(false);
    setError("");
    setUnavailable(false);
    try {
      const token = readToken();
      if (token) {
        const identity = await getIdentity(token);
        if (request !== generation.current) return;
        setUser(identity.user);
        history.replaceState(null, "", "/portal");
      } else {
        history.replaceState(null, "", "/login");
      }
    } catch (failure) {
      if (request !== generation.current) return;
      if (failure instanceof AuthError && failure.kind === "unauthenticated") {
        history.replaceState(null, "", "/login");
        try {
          clearToken();
        } catch {
          setError("Session storage is unavailable. Close this tab to end the session.");
        }
      } else if (failure instanceof AuthError && failure.kind === "storage") {
        history.replaceState(null, "", "/login");
        setError("Session storage is unavailable. Enable it to sign in.");
      } else {
        setUnavailable(true);
        setError("Authentication is unavailable. Retry or log out.");
      }
    } finally {
      if (request === generation.current) setChecking(false);
    }
  }, []);

  useEffect(() => {
    void restore();
    const navigate = () => void restore();
    const resume = (event: PageTransitionEvent) => {
      if (event.persisted) void restore();
    };
    window.addEventListener("popstate", navigate);
    window.addEventListener("pageshow", resume);
    return () => {
      generation.current++;
      window.removeEventListener("popstate", navigate);
      window.removeEventListener("pageshow", resume);
    };
  }, [restore]);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (busy) return;
    const form = event.currentTarget;
    const data = new FormData(form);
    const credentials = {
      username: String(data.get("username")),
      password: String(data.get("password")),
    };
    const password = form.elements.namedItem("password");
    if (password instanceof HTMLInputElement) password.value = "";
    const request = ++generation.current;
    setBusy(true);
    setError("");
    try {
      const result = await login(credentials);
      if (request !== generation.current) return;
      const identity = await getIdentity(result.token);
      if (request !== generation.current) return;
      storeToken(result.token);
      setUser(identity.user);
      history.replaceState(null, "", "/portal");
    } catch (failure) {
      if (request !== generation.current) return;
      setError(
        failure instanceof AuthError && failure.kind === "unauthenticated"
          ? "Check your username or password and try again."
          : "Sign-in is unavailable. Please try again later.",
      );
    } finally {
      if (request === generation.current) setBusy(false);
    }
  }


