import argparse
import json
import subprocess
from pathlib import Path

REPO='repos/PavelDobranov/gethookd-assignment'
ROOT=Path('/tmp')
STATE=ROOT/'gethookd-m4-publication.json'
items=json.loads((ROOT/'gethookd-m4-items.json').read_text())
plan_template=(ROOT/'gethookd-m4-plan.md').read_text()
state=json.loads(STATE.read_text()) if STATE.exists() else {'issues':{},'relations':[]}

def save():
    STATE.write_text(json.dumps(state,indent=2))
def api(path,method='GET',payload=None):
    cmd=['gh','api',f'{REPO}/{path}','--method',method]
    if payload is not None:
        cmd+=['--input','-']
    p=subprocess.run(cmd,input=json.dumps(payload) if payload is not None else None,text=True,capture_output=True)
    if p.returncode:
        raise RuntimeError(f'{method} {path}: {p.stderr}')
    return json.loads(p.stdout) if p.stdout.strip() else None

def create(key,title,body):
    if key in state['issues']:
        return state['issues'][key]
    x=api('issues','POST',{'title':title,'body':body})
    state['issues'][key]={'number':x['number'],'id':x['id'],'url':x['html_url']}
    save()
    print(f"Created {key}: #{x['number']} {title}",flush=True)
    return state['issues'][key]

def issue_ref(key):
    return '#'+str(state['issues'][key]['number'])

def render_item(x):
    parent=issue_ref('plan')
    deps=', '.join(issue_ref(d) for d in x['deps']) if x['deps'] else 'No unfinished implementation prerequisite; completed M3 #54. Wait for plan approval.'
    header=f"# {x['title']}\n\n**Status: proposed; waits for explicit human plan approval. No implementation performed.**\n\nSpecification: #76. Parent implementation plan: {parent}. Roadmap: #2. Task key: `{x['key']}`.\n\n"
    criteria='\n'.join('- [ ] '+c for c in x['criteria'])
    if x['kind']=='review':
        return header+f"## Review checkpoint\n\nReview the actual code, focused evidence and full regression gates from {deps}. Agent summaries alone are not acceptance. Record an explicit human decision before closing this gate.\n\n## Acceptance criteria\n\n{criteria}\n\n## Verification\n\n- [ ] Review the actual diff and task evidence; independently inspect proof where correctness is at risk.\n- [ ] Confirm `npm run build`, `npm run lint`, `npm run check` and `npm test` passed with real checks, no suppressions/skips or weakened assertions.\n- [ ] Human explicitly approves proceeding, or corrective issues are linked as blockers.\n\n## Dependencies\n\n{deps}. Native blocked-by links are authoritative. Dependent tasks remain blocked until this checkpoint is explicitly accepted. Do not depend on parent spec/plan closure.\n\n## Scope\n\nReview/evidence only. No hidden implementation or unrelated cleanup. Corrections exceeding a task's scope become separately linked blockers. Preserve #76 and all parent-plan ownership/non-goal constraints, including no Playwright until M5 and no agent edits to DESIGN.md/AI_NOTES.md."
    files='\n'.join('- `'+p+'`' for p in x['files'])
    return header+f"## Description\n\n{x['description']}\n\n## Acceptance criteria\n\n{criteria}\n\n## Verification\n\n- [ ] Run and record focused verification: `{x['focused']}`. Use red/green TDD for behavior changes; runtime/manual tasks record actual evidence.\n- [ ] Run actual root gates: `npm run build`, `npm run lint`, `npm run check`, `npm test`; fail on missing prerequisites/no tests.\n- [ ] Review the actual diff, satisfy the standing Definition of Done and record a small coherent commit where code/docs change. Later proof tasks do not replace tests for this slice.\n\n## Dependencies\n\n{deps}\n\nNative blocked-by links record prerequisites. Explicit plan approval is a status gate, not a dependency on closing the plan/spec.\n\n## Files likely touched\n\n{files}\n\nGenerated append-only Drizzle SQL/snapshots/journal accompany schema tasks; small supporting README edits accompany each slice. Register new PostgreSQL suites in explicit Vitest includes/unit exclusions in the owning task.\n\n## Estimated scope\n\nSmall/medium: at most five primary handwritten paths, one focused session. If actual primary scope grows, split before coding. Runtime acceptance raises separate corrective blockers instead of hiding source changes.\n\n## Standing boundaries\n\nPreserve #76, M1–M3 contracts, strict TypeScript/Biome, feature-first direct Drizzle and isolated PostgreSQL tests. No developer-database destruction, skipped tests, weakened assertions, suppressions, secret/raw idempotency/credential-bearing URL logs, invented response replay, quota overspend or second UI meter. No unapproved infrastructure/dependencies, MCP/Playwright/E2E before M5, CI changes or edits to user-owned DESIGN.md/AI_NOTES.md. Stop and ask if feasibility exposes a product/architecture trade-off."

def relation(kind,parent,child):
    key=f'{kind}:{parent}:{child}'
    if key in state['relations']:
        return
    if kind=='sub':
        api(f'issues/{parent}/sub_issues','POST',{'sub_issue_id':child})
    else:
        api(f'issues/{parent}/dependencies/blocked_by','POST',{'issue_id':child})
    state['relations'].append(key)
    save()
    print('Linked '+key,flush=True)

def final_plan():
    lines=['| Order | Issue | Slice / checkpoint | Blocked by |','|---|---|---|---|']
    for x in items:
        deps=', '.join(issue_ref(d) for d in x['deps']) or 'Plan approval; M3 complete'
        lines.append(f"| {x['key']} | {issue_ref(x['key'])} | {x['title']} | {deps} |")
    return plan_template.replace('<!-- TASK_INDEX -->','\n'.join(lines))

parser=argparse.ArgumentParser()
parser.add_argument('phase',choices=['create','link','verify'])
a=parser.parse_args()
if a.phase=='create':
    create('plan','M4 implementation plan — Keys, exact usage and functional Developer Portal',plan_template.replace('<!-- TASK_INDEX -->','Task issues and native dependency links are being published; the complete ordered index follows in this issue. Implementation remains unapproved.'))
    for x in items:
        create(x['key'],x['title'],render_item(x))
    api(f"issues/{state['issues']['plan']['number']}",'PATCH',{'body':final_plan()})
    print('Published complete plan index.',flush=True)
elif a.phase=='link':
    relation('sub',76,state['issues']['plan']['id'])
    parent=state['issues']['plan']['number']
    for x in items:
        relation('sub',parent,state['issues'][x['key']]['id'])
    for x in items:
        for d in x['deps']:
            relation('blocked',state['issues'][x['key']]['number'],state['issues'][d]['id'])
    if not state.get('approval_comment'):
        msg=f"Specification approval recorded from the user's explicit authorization for planning and implementation tickets. Proposed implementation plan and ordered issue index: {issue_ref('plan')}, with 23 implementation/verification/documentation tasks and 11 human-review checkpoints as native sub-issues. Native blocked-by relationships encode prerequisites and checkpoint gates. The plan proposes short PostgreSQL key-row admission and owner-row billing transactions, an authoritative monthly aggregate and optional 24-hour hashed bindings, with early feasibility proof before HTTP/UI integration. Plan {issue_ref('plan')} awaits explicit human approval; no implementation has started. Playwright remains deferred to M5; DESIGN.md/AI_NOTES.md remain user-owned."
        api('issues/76/comments','POST',{'body':msg})
        state['approval_comment']=True
        save()
    print('Hierarchy, blockers and approval/handoff comment published.',flush=True)
elif a.phase=='verify':
    parent=state['issues']['plan']['number']
    children=api(f'issues/{parent}/sub_issues?per_page=100')
    assert {x['id'] for x in children}=={state['issues'][x['key']]['id'] for x in items}
    parents_children=api('issues/76/sub_issues?per_page=100')
    assert state['issues']['plan']['id'] in {x['id'] for x in parents_children}
    p=api(f'issues/{parent}')
    assert p['body'].replace('\r\n','\n').strip()==final_plan().strip()
    edge_count=0
    for x in items:
        n=state['issues'][x['key']]['number']
        remote=api(f'issues/{n}')
        assert remote['state']=='open'
        assert remote['body'].replace('\r\n','\n').strip()==render_item(x).strip(),x['key']
        blockers=api(f'issues/{n}/dependencies/blocked_by?per_page=100')
        expected={state['issues'][d]['id'] for d in x['deps']}
        assert {b['id'] for b in blockers}==expected,x['key']
        edge_count+=len(expected)
    spec=api('issues/76')
    assert '**Status: approved by the user for technical planning and task breakdown.' in spec['body']
    print(json.dumps({'plan':p['html_url'],'sub_issues':len(children),'tasks':23,'checkpoints':11,'native_blocker_edges':edge_count,'all_bodies_verified':True,'spec_approval_verified':True},indent=2),flush=True)

